'use client';

import React from 'react';
import Image from 'next/image';
import styles from './PublicMenuCard.module.css';
import { MenuResponse } from '@/hooks/usePublicMenus';

interface PublicMenuCardProps {
    menu: MenuResponse;
}

export default function PublicMenuCard({ menu }: PublicMenuCardProps) {
    // 이미지 경로 처리 (프록시 설정에 따라 조정 필요할 수 있음)
    // 현재 API에서 /images/... 로 오는지 확인 필요하지만, 일단 그대로 사용
    const imageSrc = menu.imagesSrc
        ? (menu.imagesSrc.startsWith('http') ? menu.imagesSrc : `/api/images/${menu.imagesSrc}`)
        : null;

    return (
        <div className={styles.card}>
            <div className={styles.imageWrapper}>
                {imageSrc ? (
                    <Image
                        src={imageSrc}
                        alt={menu.korName}
                        fill
                        className={styles.image}
                        sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
                    />
                ) : (
                    <div style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#aaa' }}>
                        No Image
                    </div>
                )}
            </div>
            <div className={styles.content}>
                {menu.categoryName && (
                    <span className={styles.category}>{menu.categoryName}</span>
                )}
                <h3 className={styles.name}>{menu.korName}</h3>
                {menu.engName && <p className={styles.engName}>{menu.engName}</p>}

                <p className={styles.description}>{menu.description}</p>

                <div className={styles.footer}>
                    <span className={styles.price}>
                        {menu.price.toLocaleString()}원
                    </span>
                    {menu.isSoldOut && (
                        <span className={`${styles.badge} ${styles.soldOut}`}>SOLD OUT</span>
                    )}
                </div>
            </div>
        </div>
    );
}
